import{_ as o,c as e,o as n,ae as r}from"./chunks/framework.Bi6zybwU.js";const g=JSON.parse('{"title":"Button Element","description":"Button Element","frontmatter":{"title":"Button Element","description":"Button Element"},"headers":[],"relativePath":"guide/drag-drop-elements/button-element.md","filePath":"guide/drag-drop-elements/button-element.md"}'),a={name:"guide/drag-drop-elements/button-element.md"};function l(i,t,s,d,c,u){return n(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="button-element" tabindex="-1">Button Element <a class="header-anchor" href="#button-element" aria-label="Permalink to &quot;Button Element&quot;">​</a></h1><p>Whether it&#39;s sales, subscriptions, or any other opt-in actions, tables play a pivotal role in presenting data effectively. In this dynamic landscape, a &quot;Call to Action&quot; (CTA) button element empowers users to take prompt actions. With Ninja Tables&#39; fully customizable CTA button element, you have the tools to design compelling pricing tables, comparison tables, and WooCommerce product tables that drive results. Let’s add a Button element to our Ninja Tables!</p><h2 id="properties-of-button-element" tabindex="-1"><strong>Properties of Button Element</strong> <a class="header-anchor" href="#properties-of-button-element" aria-label="Permalink to &quot;**Properties of Button Element**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Scope</strong></th><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td><strong>General</strong></td><td>Editor box</td><td>Text Editor</td></tr><tr><td></td><td>Background Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Border Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Border Size</td><td>Numeric Value</td></tr><tr><td></td><td>Border Radius</td><td>Numeric Value</td></tr><tr><td></td><td>Full Width</td><td>Toggle On or Off</td></tr><tr><td></td><td>URL</td><td>Text Field for Link of the Button</td></tr><tr><td></td><td>Open in another tab</td><td>Toggle On or Off</td></tr><tr><td><strong>Text</strong></td><td>Font Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Font Size</td><td>Numeric Value</td></tr><tr><td></td><td>Font Style</td><td>Bold, Italic &amp; Underline</td></tr><tr><td><strong>Icon</strong></td><td>Enable Icon</td><td>Toggle On or Off</td></tr><tr><td><strong>Hover</strong></td><td>Button Hover</td><td>Toggle On or Off</td></tr></tbody></table><h3 id="general" tabindex="-1"><strong>General</strong> <a class="header-anchor" href="#general" aria-label="Permalink to &quot;**General**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Button-element-in-drag-and-drop-1-1024x598.png" alt="Button element in drag and drop"></p><ul><li>**Button Text Editor: **You can either click on the button element or edit the text in this Editor Box.</li><li><strong>Background Color:</strong> You can change the color of the Hover Background. By default, it is set to Blue.</li><li><strong>Border Color:</strong> You can change the color of the Button. By default, it is set to Black.</li><li><strong>Border Size:</strong> You can control the size of the Border of the Button Hover. By default, it is set to 0.</li><li><strong>Border Radius:</strong> You can control the radius of the Border of the Button.  By default, it is set to 5.</li><li>**Full Width: **You can toggle On or Off the Button to the Full width of the cell.</li><li><strong>URL:</strong> You can edit the link URL for the Button here.</li><li><strong>Open in another tab:</strong> You can toggle On or Off the Link behavior to open the link in the same window or in a new window.</li></ul><h3 id="text" tabindex="-1"><strong>Text</strong> <a class="header-anchor" href="#text" aria-label="Permalink to &quot;**Text**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/ninja_tables_Button_Text-1-1024x356.png" alt="Table button text"></p><ul><li><strong>Font Color</strong>: You can change the color of the text. By default, it is set to Black.</li><li><strong>Font Size</strong>: You can change the size of the text. By default, it is set to 15.</li><li><strong>Font Style</strong>: You can change the Font Style orientations. Available options are Bold, Italic, and Underline.</li></ul><h3 id="icon" tabindex="-1"><strong>Icon</strong> <a class="header-anchor" href="#icon" aria-label="Permalink to &quot;**Icon**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Button-with-icon-1024x546.png" alt="Button with icon"> Enable the icon** **option for more customization like below.</p><ul><li><strong>Icon Color:</strong> You can change the color of the Icon. By default, it is set to Black.</li><li><strong>Icon Size:</strong> You can change the size of the Icon. By default, it is set to 15.</li><li><strong>Item Spacing:</strong> You can control the space between the Icon and the Text of the Button.</li><li><strong>Choose Icon:</strong> You can upload any image as an icon for your “Text icon” element.</li><li><strong>Search Icon Library:</strong> There are plenty of Icons to choose from in the library.</li><li><strong>Icon Position:</strong> You can position the icon left or right to the text. By default, it is set to left.</li></ul><h3 id="hover" tabindex="-1"><strong>Hover</strong> <a class="header-anchor" href="#hover" aria-label="Permalink to &quot;**Hover**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Button-hover-1024x530.png" alt="Button hover"> Turn the “Button Hover” option on to get more customizing features like below-</p><ul><li><strong>Background Color:</strong> You can change the color of the Hover Background. By default, it is set to Blue.</li><li><strong>Text Color:</strong> You can change the color of the text of the Button. By default, it is set to Black.</li><li><strong>Icon Color:</strong> You can change the color of the Icon. By default, it is set to Black.</li><li><strong>Border Color:</strong> You can change the color of the Button. By default, it is set to Black.</li><li><strong>Border Size:</strong> You can control the size of the Border of the Button Hover. By default, it is set to 0.</li><li><strong>Scale:</strong> You can control the scaling of the Button on Hover. By default, it is set to 1.</li></ul><h2 id="conclusion" tabindex="-1"><strong>Conclusion</strong> <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;**Conclusion**&quot;">​</a></h2><p>We hope this documentation helps you understand the functionality of this Ninja Tables button element.  Let us know your thoughts and questions.</p>',18)])])}const p=o(a,[["render",l]]);export{g as __pageData,p as default};
